def handoff_markdown(analysis):
    m = analysis.get("metadata") or {}
    vu = analysis.get("video_understanding") or {}
    q = analysis.get("analysis_quality") or {}
    lines = [
        "# L.D.PORTO VIDEO ANALYZER V4.2 - CHATGPT HANDOFF",
        "",
        f"- Arquivo: {m.get('filename', 'unknown')}",
        f"- Duração: {stamp(m.get('duration', 0))}",
        f"- Estado: {analysis.get('analysis_status', 'unknown')}",
        "- Review padrao: references V4.2; legacy full schema 2.0 e opt-in",
        "",
        "## Leitura rápida",
        "",
        vu.get("about") or "Assunto geral não pôde ser determinado com evidência suficiente.",
        "",
        "## Cobertura",
        "",
        f"- ASR proxy: {q.get('asr')}",
        f"- Diarização: {q.get('diarization_coverage')}",
        f"- Speaker ↔ pessoa: {q.get('speaker_person_mapping_coverage')}",
        f"- Active speaker: {q.get('active_speaker_coverage')}",
        f"- Camera timeline: {q.get('camera_timeline_coverage')}",
        "",
        "## Participantes",
        "",
    ]
    for p in analysis.get("participants", []):
        lines.append(f"- {p.get('person_id') or 'PERSON_UNKNOWN'} / {', '.join(p.get('speaker_ids') or []) or 'SPEAKER_UNKNOWN'}"
                     f" — role={p.get('role')}; possible_name={p.get('possible_name') or 'null'}")
    lines += ["", "## Principais tópicos", ""]
    for t in (vu.get("main_topics") or [])[:12]:
        lines.append(f"- {stamp(t.get('start', 0))}–{stamp(t.get('end', 0))}: {t.get('topic')}")
    lines += ["", "## Story arcs", ""]
    for s in analysis.get("story_arcs", [])[:15]:
        lines.append(f"- {s.get('story_arc_id')}: {stamp(s.get('start', 0))}–{stamp(s.get('end', 0))} · standalone={s.get('standalone_score')}")
    lines += ["", "## Main moments", ""]
    for x in analysis.get("main_moments", [])[:20]:
        core = x.get("core_moment") or {}
        lines.append(f"- {x.get('moment_id')}: core {stamp(core.get('start',0))}–{stamp(core.get('end',0))}; "
                     f"corte sugerido {stamp(x.get('ideal_start',0))}–{stamp(x.get('ideal_end',0))}; "
                     f"editorial={x.get('editorial_score')}; visual={x.get('visual_score')}")
    lines += ["", "## Camera Director v3", "",
              f"- Estado: {(analysis.get('stage_status') or {}).get('19_camera_director', {}).get('status', 'unavailable')}",
              f"- Cobertura temporal: {q.get('timeline_temporal_coverage')}",
              f"- Foco resolvido: {q.get('resolved_focus_coverage')}",
              f"- Trocas/minuto: {q.get('director_switches_per_minute')}",
              f"- Duração média dos planos: {q.get('average_director_shot_seconds')}",
              f"- Split: {q.get('split_fraction')}; foco sem resolução: {q.get('unresolved_focus_fraction')}",
              "Leia camera_director_timeline.json: decisões compactadas, reasons e keyframes de movimento. "
              "Cortes source_cut/cut/safety_cut não devem ser interpolados. Full-frame usa fit_with_padding. "
              "Debug opcional em camera_director_debug.json; Analyzer recomenda e Curator renderiza."]
    lines += ["", "## Avisos", ""]
    for issue in analysis.get("issues", []):
        lines.append(f"- {issue.get('stage')}: {issue.get('message')}")
    lines += ["", "## Uso no Curator", "",
              "Use CHATGPT_ANALYSIS_HANDOFF.compact.json e second_curation_package.json. Transcricao, words e colecoes detalhadas "
              "resolvem pelos arquivos/indices referenciados. O exportador declara omissoes. Nao invente nomes, falas ou presenca visual.", ""]
    return "\n".join(lines)
